#!/usr/bin/env python3
"""Operator 281: exact packet copies and existing managed-release scripts only.

Private sources/configuration stay root-only on the server. No secret or media
URL is emitted; no grants, environment values, business records or guard edits.
"""
import base64,difflib,hashlib,io,json,os,re,shlex,subprocess,sys,time,zipfile
from pathlib import Path
PACKET_Z64=''
ROOT=Path('/root/claude-rel');PRE=ROOT/'pre662';WORK=ROOT/'w662'
SERVICES=('crm','content','tasks-mcp')
def sha(b):return hashlib.sha256(b).hexdigest()
def save(p,b):
 p.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
 with os.fdopen(os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600),'wb') as f:f.write(b)
def readjson(p):return json.loads(p.read_bytes())
def run(args,timeout=45,**kw):
 r=subprocess.run(args,capture_output=True,timeout=timeout,**kw)
 if r.returncode:
  if PRE.exists():save(PRE/('failure-'+str(time.time_ns())+'.log'),r.stdout+r.stderr)
  raise RuntimeError('command_failed:'+Path(args[0]).name+':'+str(r.returncode))
 return r.stdout
def container(s):return 'synapse-'+s+'-1'
def inspect_container(s):return json.loads(run(['docker','inspect',container(s)]))[0]
def live(path):
 if path.startswith('sites/'):
  p=Path('/opt/synapse')/path;return p.read_bytes() if p.exists() else None
 service=path.split('/')[1];name=path.split('/')[-1]
 r=subprocess.run(['docker','exec',container(service),'test','-f','/app/'+name],capture_output=True,timeout=15)
 if r.returncode==1:return None
 r.check_returncode();return run(['docker','exec',container(service),'cat','/app/'+name])
def packet():
 z=zipfile.ZipFile(io.BytesIO(base64.b64decode(PACKET_Z64)))
 data={i.filename:z.read(i) for i in z.infolist()}
 if sha(data['manifest.json'])!='71372f74a75f9b59f44c3e960b404fbb320812e8dfc09ce28f814d7641be7c62' or sha(data['SHA256SUMS'])!='77312af7d7f8a69142a3faff08e2688d3b4e760ca161473c4a11bc28616dae85':raise RuntimeError('packet_pin')
 for line in data['SHA256SUMS'].decode().splitlines():
  h,name=line.split(None,1)
  if sha(data[name])!=h:raise RuntimeError('packet_checksum')
 m=json.loads(data['manifest.json'])
 if m['packetVersion']!=2 or len(set(m['patchFiles'].values()))!=7:raise RuntimeError('packet_shape')
 return m,data
def compose_args(d):
 labels=d['Config']['Labels'];files=labels.get('com.docker.compose.project.config_files','').split(',')
 if not files or not all(Path(p).is_file() for p in files):raise RuntimeError('compose_paths')
 args=[]
 for p in labels.get('com.docker.compose.project.environment_file','').split(','):
  if p:
   if not Path(p).is_file():raise RuntimeError('env_file_missing')
   args+=['--env-file',p]
 for p in files:args+=['-f',p]
 return args
def inspect():
 PRE.mkdir(mode=0o700)
 m,data=packet();save(PRE/'packet.zip',base64.b64decode(PACKET_Z64))
 for name in ('prpatch.sh','prgo.sh','rel.sh'):
  b=(ROOT/name).read_bytes();save(PRE/name,b);print('SCRIPT',name,sha(b))
 for s in SERVICES:
  d=inspect_container(s);save(PRE/(s+'.private.json'),json.dumps(d).encode())
  args=compose_args(d);save(PRE/('args-'+s+'.json'),json.dumps(args).encode())
  image=json.loads(run(['docker','image','inspect',d['Image']]))[0];save(PRE/(s+'.image.json'),json.dumps(image).encode())
  print('LIVE',s,json.dumps({'image':d['Image'],'status':d['State']['Status'],'restarts':d['RestartCount'],'health':d['State'].get('Health',{}).get('Status'),'composeFileCount':sum(x=='-f' for x in args),'envFileCount':sum(x=='--env-file' for x in args)}))
  if d['State']['Status']!='running':raise RuntimeError('not_running:'+s)
  config=json.loads(run(['docker','compose','-p','synapse','--project-directory','/opt/synapse']+args+['config','--format','json']))
  save(PRE/(s+'.compose.private.json'),json.dumps(config).encode())
  print('COMPOSE_SERVICE',s,s in config['services'])
 for path in m['newFiles']+m['patches']+['ops/content/server.js']:
  b=live(path);n=path.replace('/','__')
  if b is not None:save(PRE/'before'/n,b)
  print('FILE',path,sha(b) if b is not None else 'ABSENT')
 for s in SERVICES:print('ALPINE',s,run(['docker','exec',container(s),'cat','/etc/alpine-release']).decode().strip())
 print('DISK',run(['df','-h','/']).decode().splitlines()[-1]);print('INSPECT662_OK');return 0
def preflight():
 m,data=packet();receipt={'files':[],'ok':False}
 for s in SERVICES:
  if inspect_container(s)['Id']!=readjson(PRE/(s+'.private.json'))['Id']:raise RuntimeError('container_changed:'+s)
 paths=m['newFiles']+m['patches']+['ops/content/server.js']
 for path in paths:
  n=path.replace('/','__');before=PRE/'before'/n;original=before.read_bytes() if before.exists() else None
  if live(path)!=original:raise RuntimeError('live_changed:'+path)
  wanted=m['targetPublicSha256'][path]
  if original is not None and sha(original)==wanted:
   receipt['files'].append({'path':path,'skip':True,'sha':wanted});print('SKIP_EXACT',path);continue
  target=PRE/'candidates'/n
  if path in m['newFiles']:
   if original is not None:raise RuntimeError('unknown_new_file:'+path)
   result=data['new/'+path]
   if sha(result)!=wanted:raise RuntimeError('new_file_hash')
   save(target,result)
  elif path=='ops/content/server.js':
   if original is None:raise RuntimeError('no_live_server')
   edits=json.loads(data['content-anchors.json'])['anchors'];result=original
   for i,e in enumerate(edits,1):
    b=e['before'].encode();a=e['after'].encode();counts=[result.count(b),result.count(a)];print('ANCHOR',i,*counts)
    if counts!=[1,0]:raise RuntimeError('anchor_count:'+str(i))
    result=result.replace(b,a,1)
   undo=result
   for e in reversed(edits):
    if undo.count(e['after'].encode())!=1:raise RuntimeError('undo_anchor_count')
    undo=undo.replace(e['after'].encode(),e['before'].encode(),1)
   if undo!=original:raise RuntimeError('server_undo')
   for marker in (b'salonCompanyApp',b'taskDispatchWorker',b'montageWatcher'):
    if result.count(marker)!=original.count(marker):raise RuntimeError('private_preservation')
   save(target,result)
   save(PRE/'content-server.diff',''.join(difflib.unified_diff(original.decode().splitlines(True),result.decode().splitlines(True),fromfile='live',tofile='candidate')).encode())
  else:
   if original is None:raise RuntimeError('existing_absent:'+path)
   patch=data[m['patchFiles'][path]]
   for chunk in re.split(rb'(?m)^@@[^\n]*\n',patch)[1:]:
    old=b''.join(l[1:] for l in chunk.splitlines(True) if l.startswith((b' ',b'-')))
    if not old or original.count(old)!=1:raise RuntimeError('patch_context:'+path)
   pp=PRE/'patches'/n;save(pp,patch);save(target,original)
   run(['patch','--dry-run','--batch','--forward','--fuzz=0',str(target),str(pp)])
   run(['patch','--batch','--forward','--fuzz=0',str(target),str(pp)])
   result=target.read_bytes();undo=PRE/'undo'/n;save(undo,result)
   run(['patch','--batch','--reverse','--fuzz=0',str(undo),str(pp)])
   if undo.read_bytes()!=original:raise RuntimeError('patch_undo:'+path)
  if path.endswith('.js'):
   s=path.split('/')[1] if path.startswith('ops/') else 'content'
   run(['docker','exec','-i',container(s),'node','--check'],input=result)
  row={'path':path,'skip':False,'before':sha(original) if original is not None else None,'sha':sha(result),'bytes':len(result),'undo':True}
  receipt['files'].append(row);print('CANDIDATE',json.dumps(row))
 receipt['ok']=True;save(PRE/'receipt.json',json.dumps(receipt,indent=2).encode());print('PREFLIGHT662_OK',len(receipt['files']));return 0
def backup(phase):
 if phase not in ('before-build','before-up'):raise RuntimeError('phase')
 receipt=readjson(PRE/'receipt.json')
 if not receipt['ok']:raise RuntimeError('preflight_required')
 r=run([str(ROOT/'rel.sh'),'snap','pr662-'+phase],timeout=180,cwd=ROOT)
 directory=Path(re.findall(rb'BK=([^\s]+)',r)[-1].decode()).resolve()
 if not directory.is_relative_to((ROOT/'bk').resolve()) or not directory.is_dir():raise RuntimeError('backup_path')
 for s in ('crm','content'):
  out=run([str(ROOT/'rel.sh'),'dbsnap',str(directory),s+'_data:'+s+'.sqlite'],timeout=180,cwd=ROOT)
  save(directory/('db-'+s+'.log'),out);print(out.decode().strip())
 for s in SERVICES:
  d=inspect_container(s);old=readjson(PRE/(s+'.private.json'))
  if d['Id']!=old['Id']:raise RuntimeError('container_changed:'+s)
  save(directory/(s+'.private.json'),json.dumps(d).encode())
  # Pin existing local image so rollback survives ordinary untagged-image pruning.
  run(['docker','image','tag',d['Image'],'synapse-'+s+':rollback-pr662'])
 for row in receipt['files']:
  f=PRE/'before'/row['path'].replace('/','__')
  if f.exists():save(directory/'runtime-before'/f.name,f.read_bytes())
 save(PRE/('backup-'+phase+'.json'),json.dumps({'path':str(directory),'at':time.time()}).encode())
 print('BACKUP662_OK',phase,str(directory));return 0
def main():
 if sys.argv[1:]==['inspect']:return inspect()
 if sys.argv[1:]==['preflight']:return preflight()
 if len(sys.argv)==3 and sys.argv[1]=='backup':return backup(sys.argv[2])
 raise RuntimeError('unknown_mode')
if __name__=='__main__':
 try:sys.exit(main())
 except Exception as e:
  print('STOP662',str(e) if isinstance(e,RuntimeError) else type(e).__name__);sys.exit(1)
